<script setup>
import FilterBar from '../../shared/components/FilterBar.vue';
import TablePanel from '../../shared/components/TablePanel.vue';

import { computed,onBeforeUnmount,onMounted,reactive,ref,watch } from 'vue';
import { providerNames,stateNames,money,time,canReceipt,canVerify } from './digital-model.js';
import { downloadBlob } from '../sales/sales-model.js';
const props=defineProps({vm:{type:Object,required:true},routeFilters:{type:Object,default:()=>({})}}),filters=reactive({provider:'',main_account_id:'',account_id:'',product_id:'',status:'',from:'',to:'',q:'',...props.routeFilters}),rows=ref([]),summary=ref(null),balance=ref(null),meta=reactive({current_page:1,last_page:1,total:0}),loading=ref(false),actionKeys=new Map();
let reader,revision=0,timer;
const costVisible=computed(()=>!props.vm.pos.value&&props.vm.can('data.cost')),points=computed(()=>props.vm.state.options.accounts.filter(row=>row.type==='pos'));
const mains=computed(()=>props.vm.identity.value?.account.type==='system'?props.vm.state.options.accounts.filter(row=>row.type==='main_agent'):Array.from(new Map(props.vm.state.connections.map(row=>[row.account_id,{id:row.account_id,name:row.account_name}])).values()));
async function load(page=1){
 reader?.abort();reader=new AbortController();const signal=reader.signal,expected=++revision,parameters={...filters};loading.value=true;summary.value=null;balance.value=null;
 const auxiliary=Promise.allSettled([props.vm.api.summary(parameters,signal),!props.vm.pos.value?props.vm.api.connections({provider:parameters.provider,main_account_id:parameters.main_account_id,per_page:1},signal):Promise.resolve({balance:null})]).then(results=>{if(expected!==revision)return;for(const [index,result] of results.entries()){if(result.status==='fulfilled'){if(index===0)summary.value=result.value.data;else balance.value=result.value.balance;}else if(result.reason.name!=='AbortError')props.vm.failure(result.reason).then(message=>{if(expected===revision)props.vm.state.error=message;});}});
 try{const list=await props.vm.api.orders({...parameters,page},signal);if(expected!==revision)return;rows.value=list.data;Object.assign(meta,list.meta);}
 catch(error){if(error.name!=='AbortError'&&expected===revision)props.vm.state.error=await props.vm.failure(error);}
 finally{if(expected===revision)loading.value=false;}
 await auxiliary;
}
async function act(order,action){const id=`${order.id}:${action}`;if(!actionKeys.has(id))actionKeys.set(id,props.vm.key());const result=await props.vm.execute({version:order.version},actionKeys.get(id),(body,signal)=>props.vm.api.action(order.id,action,body,signal),action==='refund-status'?'تم التحقق من نتيجة الشركة.':'تم التحقق من الطلب نفسه.');if(result)await load(meta.current_page);}
async function exportRows(){try{downloadBlob(await props.vm.api.export(filters,props.vm.signal),'digital-services.csv');}catch(error){props.vm.state.error=await props.vm.failure(error);}}
async function refreshBalances(){if(props.vm.state.busy)return;props.vm.state.busy=true;try{let page=1,last=1;do{const response=await props.vm.api.connections({provider:'topup',main_account_id:filters.main_account_id,page,per_page:100},props.vm.signal);last=response.meta.last_page;for(const connection of response.data)await props.vm.api.balance(connection.id,props.vm.signal);page++;}while(page<=last);await props.vm.load();await load(meta.current_page);}catch(error){props.vm.state.error=await props.vm.failure(error);}finally{props.vm.state.busy=false;}}
watch(()=>props.routeFilters,next=>Object.assign(filters,next));
watch(filters,()=>{clearTimeout(timer);timer=setTimeout(()=>load(),250);});onMounted(()=>load());onBeforeUnmount(()=>{clearTimeout(timer);reader?.abort();revision++;rows.value=[];});
defineExpose({load});
</script>
<template><section class="card"><div class="toolbar"><h3>سجل الخدمات الإلكترونية</h3><div class="actions"><button v-if="!vm.pos.value&&vm.state.connections.some(row=>row.provider==='topup')" class="btn" :disabled="vm.state.busy||!vm.state.connections.some(row=>row.provider==='topup'&&row.gateway.configured)" @click="refreshBalances">تحديث رصيد Topup</button><button v-if="vm.can('digital.export')" class="btn" :disabled="vm.state.busy" @click="exportRows">تصدير السجل</button><button class="btn" :disabled="loading" @click="load(meta.current_page)">تحديث</button></div></div><FilterBar collapsible class="digital-filters"><label>الخدمة<select v-model="filters.provider"><option value="">الكل</option><option v-for="(name,id) in providerNames" :key="id" :value="id">{{name}}</option></select></label><label v-if="!vm.pos.value">الوكيل<select v-model="filters.main_account_id"><option value="">الكل</option><option v-for="row in mains" :key="row.id" :value="row.id">{{row.name}}</option></select></label><label>النقطة<select v-model="filters.account_id"><option value="">الكل</option><option v-for="row in points" :key="row.id" :value="row.id">{{row.name}}</option></select></label><label>الفئة<select v-model="filters.product_id"><option value="">الكل</option><option v-for="row in vm.state.options.products" :key="row.id" :value="row.id">{{row.name}}</option></select></label><label>الحالة<select v-model="filters.status"><option value="">الكل</option><option v-for="(name,id) in stateNames" :key="id" :value="id">{{name}}</option></select></label><label>من تاريخ<input v-model="filters.from" type="date"></label><label>إلى تاريخ<input v-model="filters.to" type="date"></label><label>بحث<input v-model="filters.q" type="search" placeholder="الموظف، رقم الزبون أو العملية" maxlength="160"></label></FilterBar><div v-if="summary" class="digital-totals"><div v-if="balance?.total" class="digital-balance-card"><span>{{filters.main_account_id?'الرصيد المتبقي للوكيل':'إجمالي الرصيد المتبقي · Topup'}}</span><b>{{balance.amount===null?'لم يُجلب بعد':money(balance.amount)+' د.ع'}}</b><small v-if="balance.updated_at">أقدم جلب ضمن الإجمالي: {{time(balance.updated_at)}} · حدّث الرصيد لمعرفة الحالي</small><small v-if="balance.known<balance.total">الرصيد المتوفر: {{balance.known}} / {{balance.total}} · حدّث الرصيد لإكمال الإجمالي</small></div><div v-if="costVisible"><span>كلفة العمليات المؤكدة</span><b>{{summary.cost===null?'غير مؤكد بالكامل':money(summary.cost)+' د.ع'}}</b><small v-if="summary.catalog_cost_count">إجمالي تقديري: {{money(summary.estimated_cost)}} د.ع · {{summary.catalog_cost_count}} عملية بكلفة تقديرية</small></div><div v-if="!balance?.total||!costVisible"><span>مبيعات ناجحة</span><b>{{money(summary.retail)}} د.ع</b></div><div><span>عدد المبيعات</span><b>{{summary.quantity}}</b></div></div><div v-if="summary?.pending||summary?.refunds" class="digital-status-summary"><span v-if="summary.refunds">مرتجعات: {{summary.refunds}}</span><span v-if="summary.pending">بانتظار التحقق / التنفيذ: {{summary.pending}}</span></div><TablePanel :start="(meta.current_page-1)*25+1" class="tablewrap" :aria-busy="loading"><table><thead><tr><th>العملية / الوقت</th><th>الخدمة / الوكيل</th><th>النقطة / الموظف</th><th>الفئة / رقم الزبون</th><th v-if="costVisible">الكلفة</th><th v-if="!vm.pos.value">سعر المدير / زيادة الوكيل</th><th>مبلغ البيع</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><span class="mono">{{row.request_id}}</span><small>{{time(row.created_at)}}</small></td><td>{{providerNames[row.provider]}}<small>{{row.main_account_name}}</small></td><td>{{row.account_name}}<small>{{row.creator_name}}</small></td><td>{{row.product_name}}<small class="mono">{{row.mobile||'—'}}</small></td><td v-if="costVisible">{{money(row.cost)}}<small v-if="row.cost_basis==='catalog_snapshot'">{{row.manual_category_name?'سعر الفئة اليدوي · كلفة تقديرية':'بحسب قائمة الشركة وقت الطلب'}}</small></td><td v-if="!vm.pos.value">{{row.admin_price===undefined?'—':money(row.admin_price)}}<small v-if="row.agent_markup!==undefined">زيادة الوكيل: {{money(row.agent_markup)}} د.ع</small></td><td>{{money(row.retail)}}</td><td><span class="badge" :class="row.status==='succeeded'?'good':['pending','review'].includes(row.status)?'warn':'neutral'">{{stateNames[row.status]}}</span><small v-if="row.message">{{row.message}}</small><small v-if="row.receipt_missing">أكدت الشركة عملية الشراء، لكن رمز البطاقة لم يصل؛ يلزم مراجعة الشركة ولا يعاد شراء البطاقة.</small><small v-if="row.reservation_active&&row.verification_supported===false">مسار التحقق غير وارد في وثيقة المزود الحالية؛ راجع مرجع الطلب لدى الشركة.</small></td><td><div class="actions"><button v-if="canReceipt(row,vm.identity.value,vm.can)" class="btn small" @click="vm.openReceipt(row)">الإيصال</button><button v-if="canVerify(row,vm.identity.value,vm.can)" class="btn small" :disabled="vm.state.busy" @click="act(row,'verify')">تحقق من النتيجة</button><button v-if="vm.identity.value?.account.type==='system'&&vm.can('digital.refund')&&(row.status==='succeeded'||row.status==='review'&&row.company_purchase_confirmed)&&row.refund_verification_supported!==false" class="btn small" :disabled="vm.state.busy" @click="act(row,'refund-status')">تحقق من استرجاع الشركة</button></div></td></tr><tr v-if="!rows.length"><td :colspan="costVisible?8:7" class="empty">{{loading?'جارٍ التحميل…':'لا توجد عمليات مطابقة'}}</td></tr></tbody></table></TablePanel><div class="formfoot"><button class="btn small" :disabled="loading||meta.current_page<=1" @click="load(meta.current_page-1)">السابق</button><span>{{meta.current_page}} / {{meta.last_page}} · {{meta.total}}</span><button class="btn small" :disabled="loading||meta.current_page>=meta.last_page" @click="load(meta.current_page+1)">التالي</button></div></section></template>
